from itertools import combinations
class BumpGAM(GaussianGAM):
 def __init__(self,dims,knots=3,alpha=1,amp_pen=.1):super().__init__(knots,alpha);self.dims=dims;self.amp_pen=amp_pen
 def kernel(self,x,p):
  n=len(self.dims);return np.exp(-.5*np.sum(((x[self.dims].values-p[:n])/p[n:])**2,axis=1))
 def fit(self,x,y):
  self.prep=ColumnTransformer([('num',make_pipeline(SplineTransformer(n_knots=self.knots,degree=3,include_bias=False),StandardScaler()),self.cols),('cat',OneHotEncoder(drop='first'),cat)])
  z=self.prep.fit_transform(x);z=np.c_[np.ones(len(z)),z]; reg=np.eye(z.shape[1])*self.alpha;reg[0,0]=0
  A=solve(z.T@z+reg,z.T,assume_a='pos');R=np.eye(len(z))-z@A;Ry=R@y
  def obj(p):
   g=self.kernel(x,p);gy=g@Ry;gg=g@R@g+self.amp_pen;amp=np.clip(gy/gg,0,800);return -2*amp*gy+amp*amp*gg
  init={'solutionizing_temp':(1120,70),'aging_temp':(600,35),'aging_time':(30,20),'cooling_rate':(35,10)}
  cbounds={'solutionizing_temp':(1000,1200),'aging_temp':(560,650),'aging_time':(5,45),'cooling_rate':(20,50)}
  sbounds={'solutionizing_temp':(20,180),'aging_temp':(8,120),'aging_time':(5,100),'cooling_rate':(3,40)}
  p0=[init[c][0] for c in self.dims]+[init[c][1] for c in self.dims];bounds=[cbounds[c] for c in self.dims]+[sbounds[c] for c in self.dims]
  opt=minimize(obj,p0,bounds=bounds,method='Nelder-Mead',options={'maxiter':2200,'xatol':1e-5})
  self.params=opt.x;g=self.kernel(x,opt.x);self.amp=np.clip((g@Ry)/(g@R@g+self.amp_pen),0,800);self.coef=A@(y-self.amp*g)
  return self

procs=['solutionizing_temp','aging_temp','aging_time','cooling_rate'];res=[]
for k in [2,3,4]:
 for dims in combinations(procs,k):
  dims=list(dims);pred=np.zeros(len(y));pars=[]
  for i,j in cv.split(X):
   m=BumpGAM(dims).fit(X.iloc[i],y[i]);pred[j]=m.predict(X.iloc[j]);pars.append(np.r_[m.params,m.amp])
