class Active(Kernel):
 def __init__(self,kernel,dims):self.kernel=kernel;self.dims=dims
 @property
 def theta(self):return self.kernel.theta
 @theta.setter
 def theta(self,t):self.kernel.theta=t
 @property
 def bounds(self):return self.kernel.bounds
 @property
 def hyperparameters(self):return self.kernel.hyperparameters
 def __call__(self,X,Y=None,eval_gradient=False):return self.kernel(X[:,self.dims],None if Y is None else Y[:,self.dims],eval_gradient=eval_gradient)
 def diag(self,X):return self.kernel.diag(X[:,self.dims])
 def is_stationary(self):return self.kernel.is_stationary()
 def __repr__(self):return str(self.dims)+':'+str(self.kernel)
