from sklearn.preprocessing import FunctionTransformer
from sklearn.linear_model import Ridge
from scipy.optimize import minimize
class FlexModel:
 def __init__(self,power=1,knots=3,alpha=1,correlation=False):self.power=power;self.knots=knots;self.alpha=alpha;self.correlation=correlation
 def tf(self,x):
  x=x.copy();x[comp]=x[comp]**self.power;return x
 def kernel(self,x,p):
  u=(x.solutionizing_temp.values-p[0])/p[3];v=(x.aging_temp.values-p[1]-(p[6]*(x.solutionizing_temp.values-p[0]) if len(p)>6 else 0))/p[4];w=(x.cooling_rate.values-p[2])/p[5];return np.exp(-.5*(u*u+v*v+w*w))
 def fit(self,x,y):
  self.prep=ColumnTransformer([('num',make_pipeline(SplineTransformer(n_knots=self.knots,degree=3,include_bias=False),StandardScaler()),comp+proc),('irrelevant',StandardScaler(),irrelevant),('cat',OneHotEncoder(drop='first'),cat)])
  z=self.prep.fit_transform(self.tf(x));z=np.c_[np.ones(len(z)),z];reg=np.eye(z.shape[1])*self.alpha;reg[0,0]=0
  A=solve(z.T@z+reg,z.T,assume_a='pos');R=np.eye(len(z))-z@A;Ry=R@y
  def obj(p):
   g=self.kernel(x,p);return -(g@Ry)**2/(g@R@g+.1)
  init=[1100,600,35,65,20,8];bounds=[(1000,1200),(560,650),(20,50),(20,180),(8,120),(3,40)]
  if self.correlation:init+=[.5];bounds+=[(-1,1)]
  opt=minimize(obj,init,bounds=bounds,method='Nelder-Mead',options={'maxiter':1800,'xatol':1e-5})
  self.params=opt.x;g=self.kernel(x,opt.x);self.amp=(g@Ry)/(g@R@g+.1);self.coef=A@(y-self.amp*g)
  return self
 def predict(self,x):return np.c_[np.ones(len(x)),self.prep.transform(self.tf(x))]@self.coef+self.amp*self.kernel(x,self.params)

